/**
 * The full emblem, name on the ribbon, as an image: footer, root language
 * gate and root 404. The files are generated by `npm run icons` from the
 * same geometry as the header mark. Width and height are always set from the
 * emblem's exact aspect ratio, so the image reserves its box and nothing
 * shifts when it loads.
 *
 * Never below 150px wide: under that the name on the ribbon stops reading,
 * and the plain-ribbon mark (Logo.tsx) is the right reading.
 */
import { ASPECT } from '../data/logo.mjs';
import type { Lang } from '../data/i18n';
import { altFor } from '../data/image-alt';

interface Props {
  lang: Lang;
  reversed?: boolean;
  width?: number;
  /** 'lazy' below the fold (the footer), so it never competes with the hero. */
  loading?: 'eager' | 'lazy';
  className?: string;
}

export default function LogoEmblem({
  lang,
  reversed = false,
  width = 160,
  loading = 'eager',
  className,
}: Props) {
  if (width < 150) throw new Error('LogoEmblem: the lettered emblem needs at least 150px');
  const src = reversed ? '/images/logo-emblem-reversed.svg' : '/images/logo.svg';
  return (
    <img
      className={className}
      src={src}
      width={width}
      height={Math.round(width * ASPECT)}
      alt={altFor(reversed ? 'logo-emblem-reversed' : 'logo', lang)}
      loading={loading}
      decoding="async"
    />
  );
}
